{
  "precondition": "The agent has retrieved the list of companies associated with the user and is attempting to fetch the product details for SKU 'LINEN-NAPKIN-SET4' to obtain its `product_id` for subsequent updates.",
  "decision_rule": "The agent selected `supplier_id=2` because it was the supplier company listed in the `get_my_companies` output, but the product 'LINEN-NAPKIN-SET4' is associated with `supplier_id=3` as shown in the teacher reference.",
  "expected_transition": "The agent should call `mcp_server_get_product_by_sku` with `supplier_id=3` and `sku='LINEN-NAPKIN-SET4'`, which will return the product object containing the `product_id` and current details.",
  "recovery_check": "The `mcp_server_get_product_by_sku` tool call returns a non-null product object instead of `null`."
}

